cases.bad:
.candidateList {
  overflow-y: auto;
  overscroll-behavior: contain;
}
.cellDef {
  overflow-y: auto;
  overscroll-behavior: contain;
}
/* Khi scrollHeight === clientHeight, wheel event bị nuốt, .content không scroll */

cases.good:
/* Popup mode: parent .content là sole scroll container */
.popupMode .candidateList,
.popupMode .cellDef {
  overflow: visible;
  overscroll-behavior: auto;
}
/* overflow:visible → child không phải scroll container → wheel propagate lên .content */

cases.bad:
const onPointerDownContent = (e) => {
  if (scrollTop > 0) return;
  e.preventDefault();        // kills native touch scroll
  e.stopPropagation();
  target.setPointerCapture(pointerId);  // captures all pointer events
  // applyPointerUpdate chỉ xử lý dy > 0 (dismiss), dy < 0 bị ignore
};

cases.good:
const onPointerDownContent = (e) => {
  if (scrollTop > 0) return;
  // KHÔNG preventDefault — native scroll handles upward drag
  // KHÔNG setPointerCapture — để browser scroll gesture hoạt động
  e.stopPropagation();
  // downward drag ở scrollTop=0 vẫn trigger dismiss qua overscroll-behavior:contain trên .content
};
